        if (business.equals("APPROVAL")) {
            if (restricted) {
                return "DENY";
            }
            if (amount <= 1000) {
                return "AUTO";
            }
            return "MANUAL";
        }

        if (!paid || days > 7) {
            return "DENY";
        }
        if (amount <= 1000) {
            return "AUTO";
        }
        return "MANUAL";
    }
}
